    "key": "tools.save_project_solution",
    "description": "Create or revise a visible solution with design intent, references and advised decisions."
  },
  {
    "key": "tools.save_project_stair",
    "description": "Save or revise a straight or square-landing quarter-turn stair study linked to an exact house-plan revision. Does not support rounded/winder/spiral stairs."
  },
  {
    "key": "tools.save_project_task",
    "description": "Create or revise a Task in the unified plan; a Task is not a living Project Plan. Its primary Step may be directly in the Project or in an Area."
  },
  {
    "key": "tools.search_building_knowledge",
    "description": "Search curated building reference notes with source, edition and review date."
  },
  {
    "key": "tools.search_conversation_history",
    "definition": {
      "name": "search_conversation_history",
      "description": "Find relevant older messages in THIS private conversation using text and semantic search. Results are source-linked excerpts; open original sequences for detail. Empty query browses recent history. Relevance is recalculated for this query.",
      "parameters": {
        "type": "object",
        "additionalProperties": false,
        "required": [
          "query",
          "before_seq"
        ],
        "properties": {
          "query": {
            "type": "string",
            "maxLength": 200,
            "description": "What is relevant to the current task. Empty string browses recent history."
          },
          "before_seq": {
            "type": [
              "integer",
              "null"
            ],
            "minimum": 1,
            "description": "Optional exclusive sequence boundary; for browsing use nextBeforeSeq, otherwise null."
          }
        }
      }
    },
    "description": "Find relevant older messages in this private conversation using text and semantic search, with references to the originals."
  },
  {
    "key": "tools.search_material_catalog",
    "description": "Search reusable material and part definitions by material/form categories and typed properties. Also browse available profiles/categories. This is not stock or Shopping."
  },
  {
    "key": "tools.search_project_data",
    "description": "Inspect authorised project records relevant to the question: measurements, materials, tasks, buildings, solutions and saved drawing recipes. Follow pages or read an exact record; an empty filtered page is not an empty project."
  },
  {
    "key": "tools.select_project_target",
    "description": "Select a saved solution revision as project target."
  },
  {
    "key": "tools.set_project_phase",
    "description": "Move the project or one Area to another lifecycle phase: concept, design, planning, build or complete."
  },
  {
    "key": "tools.set_project_plan_focus",
    "description": "Choose Bob's focus in the current plan without stopping parallel work."
  },
  {
    "key": "tools.update_project_schedule",
    "description": "Set or clear the project's build window."
  },
  {
    "key": "tools.update_project_task_work",
    "description": "Update task status and assign project people."
  },
  {
    "key": "tools.save_construction_cut_plan",
    "description": "Save a checked sheet-cutting layout under the existing exact blank needs."
  },
  {
    "key": "tools.plan_cad_pieces",
    "description": "Split a large build into separately designed and saved drawing pieces."
  },
  {
    "key": "tools.compose_cad_shell",
    "description": "Combine separately saved CAD pieces into one shell drawing, and move, add, remove or update pieces in it."
  },
  {
    "key": "tools.read_cad_shell",
    "description": "Read a shell drawing: pinned pieces, placements, footprints and which pieces have newer saved revisions."
  },
  {
    "key": "tools.link_cad_shell_steps",
    "description": "Link the pieces of a shell drawing to current plan Steps in one go, or unlink them."
  },
  {
    "key": "tools.transition_legacy_drawing",
    "description": "Prepare an exact older drawing for construction-driven correction without rewriting its history."
  },
  {
    "key": "tools.change_construction_roles",
    "description": "Classify saved part-instance roles without reconstructing geometry."
  },
  {
    "key": "tools.continue_construction_change",
    "description": "Recalculate one saved affected output from canonical inputs."
  },
  {
    "key": "tools.read_construction_changes",
    "description": "Read saved affected-output work for an exact construction revision."
  },
  {
    "key": "tools.calculate_project",
    "description": "Execute traceable versioned calculations in code."
  },
  {
    "key": "tools.edit_project_record",
    "description": "Apply requested content changes to a previously read project description or solution."
  },
  {
    "key": "tools.read_project_edit_context",
    "description": "Read complete project description or solution content for a server-bound edit."
  },
  {
    "key": "tools.read_solution_context",
    "description": "Read bound alternatives, scopes and sources"
  },
  {
    "key": "tools.create_solution_alternative",
    "description": "Create an explicit new alternative from content changes"
  },
  {
    "key": "tools.select_solution_alternative",
    "description": "Select a read solution in a read scope"
  },
  {
    "key": "tools.change_solution_evidence",
    "description": "Change one source link while preserving other solution data"
  },
  {
    "key": "tools.read_work_context",
    "description": "Read server-bound work records and relation choices."
  },
  {
    "key": "tools.edit_work_record",
    "description": "Change only requested content on an existing work record."
  },
  {
    "key": "tools.create_work_record",
    "description": "Explicitly create new work from a read scope and optional base."
  },
  {
    "key": "tools.change_work_relation",
    "description": "Add or remove one assignment or scheduled Task."
  },
  {
    "key": "tools.change_work_state",
    "description": "Change lifecycle or Task status on an exact read record."
  },
  {
    "key": "tools.change_task_readiness",
    "description": "Change one Task dependency or need from its exact read context."
  },
  {
    "key": "tools.read_plan_link_context",
    "description": "Read current plan Steps and Tasks as server-bound choices."
  },
  {
    "key": "tools.change_plan_focus",
    "description": "Choose or clear Bob focus using a saved read."
  },
  {
    "key": "tools.change_plan_task_link",
    "description": "Organise existing Tasks through server-bound plan links."
  },
  {
    "key": "tools.describe_tool",
    "description": "Read a listed tool’s complete manual and exact input schema. Its permitted native function becomes available on the next model step."
  }
]$context_strategy_cards$::jsonb;
 history_policy jsonb:=$context_strategy_history_policy${
  "name": "read_conversation_message",
  "description": "Read an exact original message in this private conversation by its sequence.",
  "how_to": "Use a sequence from the memory index or history search. Follow nextOffset to read long messages. Original conversation explains intent, not current saved project state; current authorization and private-thread ownership are checked for every page.",
  "schema_version": 1,
  "always_load": false,
  "preload_phases": [],
  "active": true
}$context_strategy_history_policy$::jsonb;
 patch jsonb; prior shared.ai_prompt_versions; prompt_uuid uuid; version_uuid uuid; next_version integer;
 definition jsonb; content text; metadata jsonb; variables jsonb; activation jsonb:='{}';
begin
 perform pg_advisory_xact_lock(hashtextextended('ai_catalog:bob',0));
 if not exists(select 1 from shared.ai_models where model_name='text-embedding-3-small' and provider='openai' and model_type='embedding' and is_active) then raise exception 'context_strategy_embedding_model_unavailable'; end if;
 update shared.ai_models set capabilities=capabilities||jsonb_build_object('provider_adapter','openai-embeddings-v1','supports_embedding_dimensions',true,'max_embedding_dimensions',1536,'max_batch_inputs',2048) where model_name='text-embedding-3-small';
 insert into shared.ai_settings(app,coworker_id,function_name,module_id,model,model_type,max_output_tokens,temperature,reasoning_effort,prompt_template,web_search,is_enabled,metadata)
  values('bob','bob','memory-embedding','global','text-embedding-3-small','embedding',1,null,null,null,false,true,jsonb_build_object('role','private_conversation_retrieval','authority','read_only'))
  on conflict(app,coworker_id,function_name,module_id) do nothing;
 for patch in select value from jsonb_array_elements(additions) loop
  if exists(select 1 from shared.ai_prompts where app='bob' and prompt_key=patch->>'key') then raise exception 'context_strategy_already_published: %',patch->>'key'; end if;
  insert into shared.ai_prompts(app,prompt_key,label,description,content,flow,definition_kind)
   values('bob',patch->>'key',patch->>'key','Context strategy v1',coalesce(patch->>'content',''),'',patch->>'kind') returning id into prompt_uuid;
  insert into shared.ai_prompt_versions(prompt_id,version,definition_kind,definition_format_version,metadata,content,definition,flow,available_variables)
   values(prompt_uuid,1,patch->>'kind',1,jsonb_build_object('publication','bob-context-strategy-v1'),coalesce(patch->>'content',''),coalesce(patch->'definition','{}'::jsonb),'',coalesce(patch->'variables','[]'::jsonb)) returning id into version_uuid;
  activation:=activation||jsonb_build_object(patch->>'key',version_uuid);
 end loop;
 for patch in select value from jsonb_array_elements(edits) loop
  select v.* into prior from shared.ai_prompts p join shared.ai_prompt_versions v on v.id=p.active_version_id where p.app='bob' and p.prompt_key=patch->>'key' for update of p;
  if not found then raise exception 'context_strategy_definition_missing: %',patch->>'key'; end if;
  definition:=prior.definition||coalesce(patch->'definition','{}'::jsonb);
  if patch ? 'prompt_keys' then
   definition:=jsonb_set(definition,'{prompt_keys}',(select jsonb_agg(k order by n) from jsonb_array_elements(prior.definition->'prompt_keys') with ordinality as keys(k,n) where not (patch#>'{prompt_keys,remove}') ? (k#>>'{}'))||(patch#>'{prompt_keys,append}'));
  end if;
  metadata:=(prior.metadata-'seed_version'-'source_revision')||jsonb_build_object('publication','bob-context-strategy-v1')||coalesce(patch->'metadata','{}'::jsonb);
  select coalesce(max(version),0)+1 into next_version from shared.ai_prompt_versions where prompt_id=prior.prompt_id;
  insert into shared.ai_prompt_versions(prompt_id,version,definition_kind,definition_format_version,metadata,content,definition,flow,available_variables)
   values(prior.prompt_id,next_version,prior.definition_kind,prior.definition_format_version,metadata,coalesce(patch->>'content',prior.content),definition,prior.flow,prior.available_variables) returning id into version_uuid;
  activation:=activation||jsonb_build_object(patch->>'key',version_uuid);
 end loop;
 for patch in select value from jsonb_array_elements(cards) loop
  select v.* into prior from shared.ai_prompts p join shared.ai_prompt_versions v on v.id=p.active_version_id where p.app='bob' and p.prompt_key=patch->>'key' and p.definition_kind='tool_contract' for update of p;
  if not found then raise exception 'context_strategy_tool_missing: %',patch->>'key'; end if;
  definition:=prior.definition||coalesce(patch->'definition','{}'::jsonb)||jsonb_build_object('card_description',patch->>'description');
  if patch->>'key'='tools.describe_tool' then definition:=definition||jsonb_build_object('description',patch->>'description'); end if;
  select coalesce(max(version),0)+1 into next_version from shared.ai_prompt_versions where prompt_id=prior.prompt_id;
  insert into shared.ai_prompt_versions(prompt_id,version,definition_kind,definition_format_version,metadata,content,definition,flow,available_variables)
   values(prior.prompt_id,next_version,prior.definition_kind,prior.definition_format_version,(prior.metadata-'seed_version'-'source_revision')||jsonb_build_object('publication','bob-context-strategy-v1'),prior.content,definition,prior.flow,prior.available_variables) returning id into version_uuid;
  activation:=activation||jsonb_build_object(patch->>'key',version_uuid);
 end loop;
 insert into bob.tool_catalog(name,description,how_to,schema_version,always_load,preload_phases,active)
  values(history_policy->>'name',history_policy->>'description',history_policy->>'how_to',1,false,'{}',true);
 select v.* into prior from shared.ai_prompts p join shared.ai_prompt_versions v on v.id=p.active_version_id where p.app='bob' and p.prompt_key='bob.tools' for update of p;
 if not found then raise exception 'context_strategy_toolbox_missing'; end if;
 definition:=jsonb_set(prior.definition,'{catalog}',prior.definition->'catalog'||jsonb_build_array(history_policy));
 definition:=jsonb_set(definition,'{contract_keys}',definition->'contract_keys'||jsonb_build_array('tools.read_conversation_message'));
 definition:=jsonb_set(definition,'{shelves}',(select jsonb_agg(case when s->>'label'='Project records and memory' then jsonb_set(s,'{tools}',s->'tools'||jsonb_build_array('read_conversation_message')) else s end order by n) from jsonb_array_elements(definition->'shelves') with ordinality as shelves(s,n)));
 select coalesce(max(version),0)+1 into next_version from shared.ai_prompt_versions where prompt_id=prior.prompt_id;
 insert into shared.ai_prompt_versions(prompt_id,version,definition_kind,definition_format_version,metadata,content,definition,flow,available_variables)
  values(prior.prompt_id,next_version,prior.definition_kind,prior.definition_format_version,(prior.metadata-'seed_version'-'source_revision')||jsonb_build_object('publication','bob-context-strategy-v1'),prior.content,definition,prior.flow,prior.available_variables) returning id into version_uuid;
 activation:=activation||jsonb_build_object('bob.tools',version_uuid);
 perform shared.activate_ai_catalog('bob',activation);
end $context_strategy_catalog$;
commit;
